import sys
from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.nextRight = None

def connect(root):
    if not root:
        return

    queue = deque([root])

    while queue:
        level_size = len(queue)
        prev = None

        for _ in range(level_size):
            current = queue.popleft()

            if prev:
                prev.nextRight = current

            prev = current

            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)

        if prev:
            prev.nextRight = None

def level_order_traversal(root):
    if not root:
        return []

    result = []
    queue = deque([root])

    while queue:
        node = queue.popleft()
        result.append(node.data)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    return result

def inorder_with_next(root):
    if not root:
        return []

    stack = []
    result = []
    current = root

    while stack or current:
        while current:
            stack.append(current)
            current = current.left

        current = stack.pop()
        result.append(current.data)
        current = current.right

    return result

def build_tree_from_input():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return None

    n = int(lines[0])
    if n == 0:
        return None

    edges = {}
    parent_map = {}

    for i in range(1, n + 1):
        parts = lines[i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges[(u, 'L')] = v
        edges[(u, 'R')] = w
        parent_map[v] = u
        parent_map[w] = u

    root_val = None
    for val in parent_map:
        if val not in parent_map:
            root_val = val
            break

    if root_val is None and n > 0:
        root_val = list(parent_map.keys())[0]

    nodes = {}
    for val in parent_map:
        nodes[val] = Node(val)

    for (parent, side), child_val in edges.items():
        if side == 'L':
            nodes[parent].left = nodes[child_val]
        else:
            nodes[parent].right = nodes[child_val]

    return nodes[root_val]

def main():
    root = build_tree_from_input()
    connect(root)

    level_order = level_order_traversal(root)
    inorder = inorder_with_next(root)

    print(" ".join(map(str, level_order)))
    print(" ".join(map(str, inorder)))

if __name__ == "__main__":
    main()
